def is_majority(arr, n, x):    
    count = 0  # Count of elements equal to 'x'.  

    for i in range (n):        
        if arr[i] == x:         
            count += 1            

    return True if count > int(n/2) else False

def max_Product(arr):
    arr = sorted(arr) # sorting array in ascending order to find maximum and minimum numbers easily (O(nlogn)) 

    if len(set([i for i in set(arr[:-2])])) < 3:   # checking whether there are at least three unique elements or not. If yes then return product of two largest, otherwise last element will be the maximum and second smallest is minimum so we can directly get their products (O(1))
        max_product = arr[-1] * arr[-2] 
    else:   # if there are more than three unique elements in array. Then find out product of two largest numbers, one from each side or just the maximum and smallest number will be multiplied together to get a larger result (O(n))
        max_product = sorted([arr[0]* arr[-1],  arr[-2] * arr[-3]] ) # sorting array in ascending order again after multiplying two largest numbers or just the maximum and smallest number will be multiplied together to get a larger result (O(nlogn))

    return max_product[0],max_product[1] if len(max_product) > 1 else arr[-3]  # returning tuple of highest product pair, otherwise single element in array. If there are more than one elements then it will be a list (O(min(n)))

def max_subarray_product(arr):  
    if not arr: return None # handle empty array case to avoid division by zero error in Kadane's algorithm later on (line below)

    curr_max = overall_max = arr[0] 

    for i in range(1, len(arr)):  
        if arr[i] > curr_max + arr[i]: # check whether the current element is greater than sum of previous max and this one. If so then update it to be maximum value among all elements till now (line below) 
            curr_max = arr[i]  
        else:   
            curr_max += arr[i]     # if not, add the current element into sum of previous max and this one. Update as necessary in line above for next iteration(s).        

        overall_max = max(overall_max,curr_max)  # update maximum product so far (line below), at each step we are considering all subarrays ending here or not depending on whether they're greater than current sum of elements till now.  

    return overall_max if len(arr)!=1 else None;      # handle case when array has only one element, in that scenario maximum product is the single number itself (line below)

