def check_min_heap(arr): 
    n = len(arr)   # calculate length of the list/array.

    for i in range((n-2)/2, -1, -1):      # iterate from last non leaf node to first (parent nodes).
        if arr[i] > arr[(2*i + 1)]:       # check left child is smaller than parent or not. 
            return False                     # If any condition fails then it means array does't represent min heap, so we will return false here:  

        if (2*i+2 < n and arr[i] > arr[(2*i + 2)]):     # check right child is smaller than parent or not. 
            return False                     # If any condition fails then it means array does't represent min heap, so we will return false here:  

    return True                            # if all conditions are satisfied that the given list/array represents a Min Heap (Complete Binary Tree). So finally returning true.

